def build_trie(patterns: list[str]) -> ACNode:
    root = ACNode()
    for pat in patterns:
        if not pat:
            continue
        cur = root
        for ch in pat:
            cur = cur.next.setdefault(ch, ACNode())
        cur.outputs.append(pat)
    return root
