def attach_failure_links(root: ACNode) -> None:
    q: deque[ACNode] = deque()
    for child in root.next.values():
        child.fail = root
        q.append(child)
    while q:
        u = q.popleft()
        for ch, v in u.next.items():
            f = u.fail
            while f is not None and ch not in f.next:
                f = f.fail
            v.fail = f.next[ch] if f is not None else root
            v.outputs.extend(v.fail.outputs)  # Pre-merge suffix outputs
            q.append(v)
